# Let me verify my nearest-fill logic step by step

test_col5 = [3, 0, 0, 0, 0, 0, 8, 0, 0, 0, 0, 0, 0, 0, 0, 0, 5]
nz = [(r, v) for r, v in enumerate(test_col5) if v != 0]
print(f"Col 5 non-zero positions: {nz}")

# Manual calculation for key rows
print("\nManual nearest calculation:")
for r in [0, 1, 3, 4, 5, 6, 11, 12, 16]:
    if test_col5[r] != 0:
        print(f"Row {r}: value is {test_col5[r]} → output {test_col5[r]}")
    else:
        distances = [(nr, v, abs(r - nr)) for (nr, v) in nz]
        closest = min(distances, key=lambda x: x[2])
        print(f"Row {r}: distances {distances} → closest is ({closest[0]}, {closest[1]}) → output {closest[1]}")

# Now full calculation
def nearest_fill_with_tiebreak(col_vals, tiebreak='first'):
    """tiebreak='first': choose smaller row index on tie
       tiebreak='largest_val': choose larger value on tie"""
    nz = [(r, v) for r, v in enumerate(col_vals) if v != 0]
    if not nz:
        return col_vals

    tiebreak_func = {'first': 'first', 'largest_val': 'largest_val'}[tiebreak]

    result = []
    for r in range(17):
        if col_vals[r] != 0:
            result.append(col_vals[r])
        else:
            min_dist = float('inf')
            best_v = 0
            for (nr, v) in nz:
                dist = abs(r - nr)
                if dist < min_dist:
                    min_dist = dist
                    best_v = v
                elif dist == min_dist:
                    # Tie! Apply tiebreak logic
                    if tiebreak_func == 'largest_val':
                        if v > best_v:
                            best_v = v
            result.append(best_v)
    return result

print(f"\nWith first tiebreak: {nearest_fill_with_tiebreak(test_col5, 'first')}")
print(f"With largest_val tiebreak: {nearest_fill_with_tiebreak(test_col5, 'largest_val')}")

